import { Button } from '@refy-design/web';
import { Drawer } from '@refy-design/web';
import { useState } from 'react';
const footer = (close?: () => void) => (
  <div
    style={{
      display: 'flex',
      gap: 8,
      justifyContent: 'flex-end',
      alignItems: 'center',
    }}
  >
    <span
      style={{
        marginRight: 'auto',
        color: 'var(--ink-3)',
        fontFamily: 'var(--font-mono)',
        fontSize: 11,
      }}
    >
      12 items · Esc to cancel
    </span>
    <Button variant="ghost" onClick={close}>
      Cancel
    </Button>
    <Button variant="primary" onClick={close}>
      Apply
    </Button>
  </div>
);
const body = (
  <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
    <p style={{ margin: 0 }}>
      Domain analysis details: 84 pages crawled, 12 critical issues and 31 warnings.
    </p>
    <p style={{ margin: 0 }}>
      The drawer body scrolls on its own when the content is taller than the available
      space.
    </p>
    {Array.from({ length: 18 }, (_, i) => (
      <p key={i} style={{ margin: 0, color: 'var(--ink-3)' }}>
        Content item {i + 1} — filler text to show the inner scroll.
      </p>
    ))}
  </div>
);
function DrawerDemo({ side }: { side: 'left' | 'right' | 'bottom' }) {
  const [open, setOpen] = useState(false);
  return (
    <div style={{ minHeight: 420, padding: 24 }}>
      <Button onClick={() => setOpen(true)}>
        Open {side === 'bottom' ? 'bottom panel' : `drawer ${side}`}
      </Button>
      <Drawer
        open={open}
        onOpenChange={setOpen}
        side={side}
        title="Analysis details"
        footer={footer(() => setOpen(false))}
      >
        {body}
      </Drawer>
    </div>
  );
}
export function Example() {
  return <DrawerDemo side="right" />;
}

